package com.ecole.gestion_scolaire.studentportal.service; import com.ecole.gestion_scolaire.studentportal.dto.StudentPortalDtos.*; import com.ecole.gestion_scolaire.security.service.SecurityUser; import jakarta.persistence.*; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.sql.*; import java.time.*; import java.util.*;
@Service @Transactional(readOnly=true) public class StudentPortalService{@PersistenceContext EntityManager em; private SecurityUser current(){return (SecurityUser)SecurityContextHolder.getContext().getAuthentication().getPrincipal();} private Long sid(){Long p=current().getUserAccount().getPerson().getId();List<?>r=em.createNativeQuery("select id from student where person_id=:p limit 1").setParameter("p",p).getResultList();if(r.isEmpty())throw new IllegalStateException("Aucun profil élève rattaché à ce compte.");return ((Number)r.get(0)).longValue();}
 public Me me(){Object[]r=(Object[])em.createNativeQuery("select s.id,s.student_number,p.first_name,p.last_name,cg.name from student s join person p on p.id=s.person_id left join lateral(select se.* from student_enrollment se where se.student_id=s.id and se.status='ACTIVE' order by se.enrollment_date desc,se.id desc limit 1)e on true left join class_group cg on cg.id=e.current_class_group_id where s.id=:s").setParameter("s",sid()).getSingleResult();return new Me(l(r[0]),str(r[1]),str(r[2]),str(r[3]),str(r[4]));}
 private Long cg(){List<?>r=em.createNativeQuery("select current_class_group_id from student_enrollment where student_id=:s and status='ACTIVE' order by enrollment_date desc,id desc limit 1").setParameter("s",sid()).getResultList();return r.isEmpty()?null:l(r.get(0));}
 public List<Attendance> attendance(){Long id=sid();List<Object[]>rs=em.createNativeQuery("select a.id,cs.session_date,s.name,a.attendance_status,a.late_minutes,a.reason,a.justified from student_attendance a join class_session cs on cs.id=a.class_session_id join subject s on s.id=cs.subject_id where a.student_id=:s order by cs.session_date desc,a.id desc").setParameter("s",id).getResultList();List<Attendance>o=new ArrayList<>();for(Object[]r:rs)o.add(new Attendance(l(r[0]),date(r[1]),str(r[2]),str(r[3]),r[4]==null?null:((Number)r[4]).intValue(),str(r[5]),Boolean.TRUE.equals(r[6])));return o;}
 public List<Timetable> timetable(){Long c=cg();if(c==null)return List.of();List<Object[]>rs=em.createNativeQuery("select se.id,se.day_of_week,ts.start_time,ts.end_time,s.name,concat(p.first_name,' ',p.last_name),cg.name from schedule_entry se join teaching_assignment ta on ta.id=se.teaching_assignment_id join time_slot ts on ts.id=se.time_slot_id join subject s on s.id=ta.subject_id join teacher t on t.id=ta.teacher_id join employee e on e.id=t.employee_id join person p on p.id=e.person_id join class_group cg on cg.id=ta.class_group_id where ta.class_group_id=:c and se.status='ACTIVE' and ta.status='ACTIVE' order by se.day_of_week,ts.display_order").setParameter("c",c).getResultList();List<Timetable>o=new ArrayList<>();for(Object[]r:rs)o.add(new Timetable(l(r[0]),str(r[1]),str(r[2]),str(r[3]),str(r[4]),str(r[5]),str(r[6])));return o;}
 public List<Exercise> exercises(){Long c=cg();if(c==null)return List.of();List<Object[]>rs=em.createNativeQuery("select x.id,x.title,x.description,x.instructions,x.due_date,x.status,s.name,cg.name from teacher_exercise x join teaching_assignment ta on ta.id=x.teaching_assignment_id join subject s on s.id=ta.subject_id join class_group cg on cg.id=ta.class_group_id where ta.class_group_id=:c and x.status<>'DRAFT' order by x.due_date desc nulls last,x.id desc").setParameter("c",c).getResultList();List<Exercise>o=new ArrayList<>();for(Object[]r:rs)o.add(new Exercise(l(r[0]),str(r[1]),str(r[2]),str(r[3]),date(r[4]),str(r[5]),str(r[6]),str(r[7])));return o;}
 public List<Grade> grades(){Long id=sid();List<Object[]>rs=em.createNativeQuery("select ev.id,ev.title,s.name,ev.evaluation_date,ev.max_score,g.score,g.absent,g.comment from teacher_evaluation_grade g join teacher_evaluation ev on ev.id=g.evaluation_id join teaching_assignment ta on ta.id=ev.teaching_assignment_id join subject s on s.id=ta.subject_id where g.student_id=:s and ev.status<>'DRAFT' order by ev.evaluation_date desc,ev.id desc").setParameter("s",id).getResultList();List<Grade>o=new ArrayList<>();for(Object[]r:rs)o.add(new Grade(l(r[0]),str(r[1]),str(r[2]),date(r[3]),bd(r[4]),r[5]==null?null:bd(r[5]),Boolean.TRUE.equals(r[6]),str(r[7])));return o;}
 private static Long l(Object o){return o==null?null:((Number)o).longValue();}private static String str(Object o){return o==null?null:o.toString();}private static BigDecimal bd(Object o){return o==null?BigDecimal.ZERO:(o instanceof BigDecimal b?b:new BigDecimal(o.toString()));}private static LocalDate date(Object o){if(o==null)return null;if(o instanceof LocalDate d)return d;if(o instanceof java.sql.Date d)return d.toLocalDate();return LocalDate.parse(o.toString());}}
